return [
  { json: { name: 'INPS', url: 'https://www.inps.it/it/it/inps-comunica/notizie.html' } },
  { json: { name: 'INAIL', url: 'https://www.inail.it/cs/internet/comunicazione/news/' } },
  { json: { name: 'Agenzia Entrate', url: 'https://www.agenziaentrate.gov.it/portale/normativa-e-prassi/circolari' } },
  { json: { name: 'AdER', url: 'https://www.agenziaentrateriscossione.gov.it/notizie/' } },
  { json: { name: 'INL', url: 'https://www.ispettorato.gov.it/documenti-e-normativa/orientamenti-giuridici-inl/circolari/' } },
  { json: { name: 'CNCE Casse Edili', url: 'https://www.cnce.it/' } }
];

var sources = ['INPS', 'INAIL', 'Agenzia Entrate', 'AdER', 'INL', 'CNCE Casse Edili'];
var items = $input.all();
var testi = items.map(function(item, i) {
  var nome = sources[i] || ('Fonte ' + (i + 1));
  var testo = '';
  try {
    if (item.json && typeof item.json.data === 'string') {
      testo = item.json.data;
    } else if (item.json && typeof item.json.body === 'string') {
      testo = item.json.body;
    } else if (item.json && item.json.error) {
      return '=== ' + nome + ' ===\n[Errore nel recupero dati]';
    } else {
      testo = JSON.stringify(item.json || '');
    }
    testo = testo
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/\s+/g, ' ')
      .trim()
      .substring(0, 3500);
  } catch(e) {
    testo = '[Errore nel parsing: ' + String(e) + ']';
  }
  return '=== ' + nome + ' ===\n' + testo;
});
return [{ json: { contenuto: testi.join('\n\n---\n\n'), dataOggi: new Date().toISOString().split('T')[0] } }];

var items = $input.all();
var riassunto = items.length > 0 ? (items[0].json.text || '') : '';
var staticData = $getWorkflowStaticData('global');
staticData.aggiornamenti = riassunto;
staticData.ultimoAggiornamento = new Date().toISOString().split('T')[0];
return [{ json: { salvato: true, data: staticData.ultimoAggiornamento, caratteri: riassunto.length } }];

var staticData = $getWorkflowStaticData('global');
var aggiornamenti = staticData.aggiornamenti || '';
var data = staticData.ultimoAggiornamento || 'Mai aggiornato';
return [{ json: { aggiornamenti: aggiornamenti, dataAggiornamento: data, disponibile: aggiornamenti.length > 0 } }];

var staticData = $getWorkflowStaticData('global');
var riassunto = staticData.aggiornamenti || 'Nessun aggiornamento disponibile';
var dataOggi = staticData.ultimoAggiornamento || new Date().toISOString().split('T')[0];
var fonti = [
  { nome: 'INPS', desc: 'Circolari, messaggi e normativa', url: 'https://www.inps.it/it/it/inps-comunica/atti/circolari-messaggi-e-normativa.html' },
  { nome: 'INAIL', desc: 'News e comunicati', url: 'https://www.inail.it/cs/internet/comunicazione/news/' },
  { nome: 'Agenzia delle Entrate', desc: 'Circolari e normativa', url: 'https://www.agenziaentrate.gov.it/portale/normativa-e-prassi/circolari' },
  { nome: 'AdER - Riscossione', desc: 'Notizie e aggiornamenti', url: 'https://www.agenziaentrateriscossione.gov.it/notizie/' },
  { nome: 'INL - Circolari', desc: 'Circolari ispettive', url: 'https://www.ispettorato.gov.it/documenti-e-normativa/orientamenti-giuridici-inl/circolari/' },
  { nome: 'INL - Note e Pareri', desc: 'Orientamenti giuridici', url: 'https://www.ispettorato.gov.it/documenti-e-normativa/orientamenti-giuridici-inl/note-e-pareri/' },
  { nome: 'CNCE - Casse Edili', desc: 'Aggiornamenti e normativa', url: 'https://www.cnce.it/' }
];
var linksHtml = fonti.map(function(f) {
  return '<li style="margin-bottom:12px"><strong>' + f.nome + '</strong> &mdash; ' + f.desc + '<br><a href="' + f.url + '" style="color:#1a5276">' + f.url + '</a></li>';
}).join('');
var summaryEscaped = riassunto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
var html = '<!DOCTYPE html>' +
  '<html><head><meta charset="UTF-8"></head>' +
  '<body style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto;padding:20px;color:#333">' +
  '<h1 style="color:#1a5276;border-bottom:2px solid #1a5276;padding-bottom:10px">Aggiornamenti Normativi &mdash; ' + dataOggi + '</h1>' +
  '<p>Riepilogo degli aggiornamenti normativi rilevati oggi dalle principali fonti istituzionali in materia di lavoro, previdenza e fiscalit&agrave;.</p>' +
  '<h2 style="color:#2874a6">Sintesi degli Aggiornamenti</h2>' +
  '<div style="background:#eaf4fb;border-left:4px solid #2874a6;padding:15px;border-radius:4px;white-space:pre-wrap;font-size:14px;line-height:1.6">' + summaryEscaped + '</div>' +
  '<h2 style="color:#2874a6">Fonti Ufficiali</h2>' +
  '<ul style="background:#f9f9f9;padding:20px 20px 20px 35px;border-radius:4px">' + linksHtml + '</ul>' +
  '<p style="margin-top:30px;font-size:12px;color:#777;border-top:1px solid #ddd;padding-top:10px">Email generata automaticamente dal sistema n8n &mdash; ' + dataOggi + '</p>' +
  '</body></html>';
return [{ json: { html: html, subject: 'Aggiornamenti Normativi — ' + dataOggi, to: 'attilio.assirelli@gmail.com' } }];
